def transform(grid):
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    common = [v for v, _ in counts.most_common(2)]
    background = counts.most_common(1)[0][0]

    markers = {
        (r, c): grid[r][c]
        for r in range(len(grid))
        for c in range(len(grid[0]))
        if grid[r][c] not in common
    }
    ys = sorted({r for r, c in markers})
    xs = sorted({c for r, c in markers})

    out = [[background for _ in range(len(xs) - 1)] for _ in range(len(ys) - 1)]
    for i in range(len(ys) - 1):
        for j in range(len(xs) - 1):
            corners = [
                markers.get((ys[i], xs[j])),
                markers.get((ys[i], xs[j + 1])),
                markers.get((ys[i + 1], xs[j])),
                markers.get((ys[i + 1], xs[j + 1])),
            ]
            if corners[0] is not None and all(v == corners[0] for v in corners):
                out[i][j] = corners[0]
    return out
